1	package chainledger
2	
3	import (
4		"reflect"
5		"sort"
6		"strings"
7		"testing"
8	)
9	
10	func mustExportScoped(t *testing.T, graph map[string]*Lineage, source, target string) string {
11		t.Helper()
12		out, err := ExportSourceTargetLineage(graph, source, target)
13		if err != nil {
14			t.Fatalf("ExportSourceTargetLineage(%q, %q): %v", source, target, err)
15		}
16		return out
17	}
18	
19	// scopedFixture builds the spec's worked graph:
20	//
21	//	pre ──> source ──┬──> a ──────────┐
22	//	                │   ^            ├──> report ──> view
23	//	                │   └── extra    │
24	//	                ├──> b ──> mid ──┘
25	//	                ├──> sidetrack   (source downstream that never reaches report)
26	//	                └──> report (direct)
27	//
28	// report additionally depends on the independent root lone, so its full
29	// upstream closure contains ancestry that source takes no part in.
30	func scopedFixture(t *testing.T) map[string]*Lineage {
31		return buildRegisteredGraph(t, [][]string{
32			{"pre"},
33			{"source", "pre"},
34			{"extra"},
35			{"a", "source", "extra"},
36			{"b", "source"},
37			{"mid", "b"},
38			{"sidetrack", "source"},
39			{"lone"},
40			{"report", "source", "a", "mid", "lone"},
41			{"view", "report"},
42		})
43	}
44	
45	var scopedWantNodes = []string{"a", "b", "mid", "report", "source"}
46	
47	var scopedWantEdges = [][2]string{
48		{"a", "report"},
49		{"b", "mid"},
50		{"mid", "report"},
51		{"source", "a"},
52		{"source", "b"},
53		{"source", "report"},
54	}
55	
56	// The worked example from the spec: source derives report directly, through a
57	// and through b -> mid. All three routes stay complete in the scoped document;
58	// a's independent source extra (and extra -> a), source's ancestor pre,
59	// source's dead-end downstream sidetrack, report's independent upstream lone
60	// (and lone -> report) and report's downstream view all stay out.
61	func TestExportSourceTargetLineageScopedRoutes(t *testing.T) {
62		graph := scopedFixture(t)
63		before := snapshotExportGraph(graph)
64	
65		out := mustExportScoped(t, graph, "source", "report")
66		doc := parseExport(t, out)
67	
68		if !reflect.DeepEqual(doc.Nodes, scopedWantNodes) {
69			t.Errorf("nodes = %v, want %v", doc.Nodes, scopedWantNodes)
70		}
71		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, scopedWantEdges) {
72			t.Errorf("edges = %v, want %v", got, scopedWantEdges)
73		}
74		for _, excluded := range []string{"pre", "extra", "sidetrack", "lone", "view"} {
75			for _, node := range doc.Nodes {
76				if node == excluded {
77					t.Errorf("nodes must not contain %q: %v", excluded, doc.Nodes)
78				}
79			}
80		}
81		assertGraphUnchanged(t, before, graph)
82	}
83	
84	// The exact JSON text is pinned: same shape and ordering rules as the full
85	// export, restricted to the scoped node set.
86	func TestExportSourceTargetLineageExactJSON(t *testing.T) {
87		graph := scopedFixture(t)
88	
89		out := mustExportScoped(t, graph, "source", "report")
90		want := `{"nodes":["a","b","mid","report","source"],` +
91			`"edges":[{"from":"a","to":"report"},{"from":"b","to":"mid"},` +
92			`{"from":"mid","to":"report"},{"from":"source","to":"a"},` +
93			`{"from":"source","to":"b"},{"from":"source","to":"report"}]}`
94		if out != want {
95			t.Errorf("export =\n%s\nwant:\n%s", out, want)
96		}
97	}
98	
99	// The direct edge and the longer routes are all retained together. A scoped
100	// export built with only the source-side routes must be byte-identical to the
101	// fixture's result even though the fixture also has the direct edge and extra
102	// ancestry; and limiting to a sub-path keeps just that path.
103	func TestExportSourceTargetLineageKeepsLongRoutesAndSubPaths(t *testing.T) {
104		graph := buildRegisteredGraph(t, [][]string{
105			{"source"},
106			{"a", "source"},
107			{"b", "source"},
108			{"mid", "b"},
109			{"report", "source", "a", "mid"},
110		})
111	
112		doc := parseExport(t, mustExportScoped(t, graph, "source", "report"))
113		if !reflect.DeepEqual(doc.Nodes, scopedWantNodes) {
114			t.Errorf("nodes = %v, want %v", doc.Nodes, scopedWantNodes)
115		}
116		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, scopedWantEdges) {
117			t.Errorf("edges = %v, want %v", got, scopedWantEdges)
118		}
119	
120		// Scope to an intermediate target: just the source -> b -> mid route.
121		sub := parseExport(t, mustExportScoped(t, graph, "source", "mid"))
122		if !reflect.DeepEqual(sub.Nodes, []string{"b", "mid", "source"}) {
123			t.Errorf("sub-path nodes = %v", sub.Nodes)
124		}
125		if got := exportEdgeNames(sub); !reflect.DeepEqual(got, [][2]string{
126			{"b", "mid"},
127			{"source", "b"},
128		}) {
129			t.Errorf("sub-path edges = %v", got)
130		}
131	
132		// Scope to a sub-path starting at an intermediate source.
133		aOnly := parseExport(t, mustExportScoped(t, graph, "a", "report"))
134		if !reflect.DeepEqual(aOnly.Nodes, []string{"a", "report"}) {
135			t.Errorf("a-scope nodes = %v", aOnly.Nodes)
136		}
137		if got := exportEdgeNames(aOnly); !reflect.DeepEqual(got, [][2]string{{"a", "report"}}) {
138			t.Errorf("a-scope edges = %v", got)
139		}
140	}
141	
142	// Nodes and edges shared by several routes (diamond merges) appear once each.
143	func TestExportSourceTargetLineageMergesOnce(t *testing.T) {
144		graph := buildRegisteredGraph(t, [][]string{
145			{"source"},
146			{"a", "source"},
147			{"b", "source"},
148			{"merge", "a", "b"},
149			{"report", "merge", "a"},
150		})
151	
152		doc := parseExport(t, mustExportScoped(t, graph, "source", "report"))
153		wantNodes := []string{"a", "b", "merge", "report", "source"}
154		if !reflect.DeepEqual(doc.Nodes, wantNodes) {
155			t.Errorf("nodes = %v, want %v", doc.Nodes, wantNodes)
156		}
157		wantEdges := [][2]string{
158			{"a", "merge"},
159			{"a", "report"},
160			{"b", "merge"},
161			{"merge", "report"},
162			{"source", "a"},
163			{"source", "b"},
164		}
165		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, wantEdges) {
166			t.Errorf("edges = %v, want %v", got, wantEdges)
167		}
168	}
169	
170	// Source and target being the same registered dataset exports that dataset
171	// alone with an empty (non-null) edges array.
172	func TestExportSourceTargetLineageSameSourceAndTarget(t *testing.T) {
173		graph := buildRegisteredGraph(t, [][]string{
174			{"pre"},
175			{"source", "pre"},
176			{"a", "source"},
177		})
178	
179		out := mustExportScoped(t, graph, "source", "source")
180		if want := `{"nodes":["source"],"edges":[]}`; out != want {
181			t.Errorf("export = %s, want %s", out, want)
182		}
183		doc := parseExport(t, out)
184		if doc.Edges == nil {
185			t.Errorf("edges must decode as an empty array, got nil from %s", out)
186		}
187	}
188	
189	// Two registered datasets with no source -> target route succeed with two
190	// empty arrays: disconnected pairs, a reverse dependency, and a route that
191	// stops one hop short all keep no isolated endpoint.
192	func TestExportSourceTargetLineageUnreachable(t *testing.T) {
193		graph := buildRegisteredGraph(t, [][]string{
194			{"source"},
195			{"other"},
196			{"child", "source"},
197			{"report", "other"}, // report derives the other root: source cannot reach it
198			{"downstream", "report"},
199		})
200	
201		cases := []struct {
202			name   string
203			source string
204			target string
205		}{
206			{"disconnected", "source", "other"},
207			{"reverse dependency", "report", "other"},
208			{"route stops short", "source", "downstream"},
209			{"siblings", "child", "report"},
210		}
211		for _, tc := range cases {
212			t.Run(tc.name, func(t *testing.T) {
213				out := mustExportScoped(t, graph, tc.source, tc.target)
214				if want := `{"nodes":[],"edges":[]}`; out != want {
215					t.Errorf("export = %s, want %s", out, want)
216				}
217				doc := parseExport(t, out)
218				if len(doc.Nodes) != 0 || doc.Nodes == nil {
219					t.Errorf("nodes must be a non-nil empty array, got %#v", doc.Nodes)
220				}
221				if len(doc.Edges) != 0 || doc.Edges == nil {
222					t.Errorf("edges must be a non-nil empty array, got %#v", doc.Edges)
223				}
224			})
225		}
226	}
227	
228	// The same lineage built in different registration orders and with reordered
229	// upstream lists exports byte-identical text.
230	func TestExportSourceTargetLineageOrderIndependent(t *testing.T) {
231		first := buildRegisteredGraph(t, [][]string{
232			{"pre"},
233			{"source", "pre"},
234			{"extra"},
235			{"a", "source", "extra"},
236			{"b", "source"},
237			{"mid", "b"},
238			{"sidetrack", "source"},
239			{"lone"},
240			{"report", "source", "a", "mid", "lone"},
241			{"view", "report"},
242		})
243		second := buildRegisteredGraph(t, [][]string{
244			{"lone"},
245			{"extra"},
246			{"pre"},
247			{"source", "pre"},
248			{"a", "extra", "source"},
249			{"sidetrack", "source"},
250			{"b", "source"},
251			{"mid", "b"},
252			{"report", "lone", "mid", "a", "source"},
253			{"view", "report"},
254		})
255	
256		if got, want := mustExportScoped(t, first, "source", "report"),
257			mustExportScoped(t, second, "source", "report"); got != want {
258			t.Errorf("registration order changed the export:\nfirst:  %s\nsecond: %s", got, want)
259		}
260	}
261	
262	// With no route, even the two endpoints are unselected, so invalid UTF-8 in
263	// their names must not block the successful two-empty-arrays result: only
264	// actually selected names are encoding-checked.
265	func TestExportSourceTargetLineageUnreachableSkipsInvalidEndpointNames(t *testing.T) {
266		graph := buildRegisteredGraph(t, [][]string{
267			{"bad\xffsource"},
268			{"bad\xfetarget"},
269		})
270	
271		out, err := ExportSourceTargetLineage(graph, "bad\xffsource", "bad\xfetarget")
272		if err != nil {
273			t.Fatalf("unreachable scoped export failed on unselected names: %v", err)
274		}
275		if want := `{"nodes":[],"edges":[]}`; out != want {
276			t.Errorf("export = %s, want %s", out, want)
277		}
278	}
279	
280	// Names match by exact registered value: a case difference is unregistered.
281	func TestExportSourceTargetLineageCaseSensitive(t *testing.T) {
282		graph := buildRegisteredGraph(t, [][]string{
283			{"source"},
284			{"report", "source"},
285		})
286	
287		out, err := ExportSourceTargetLineage(graph, "Source", "report")
288		if err == nil {
289			t.Fatalf("case-different source succeeded with %q", out)
290		}
291		if !strings.Contains(err.Error(), "Source") {
292			t.Errorf("error %q must name the queried source", err)
293		}
294	
295		out, err = ExportSourceTargetLineage(graph, "source", "Report")
296		if err == nil {
297			t.Fatalf("case-different target succeeded with %q", out)
298		}
299		if !strings.Contains(err.Error(), "Report") {
300			t.Errorf("error %q must name the queried target", err)
301		}
302	}
303	
304	// Source is validated before target: its empty or missing-name error wins
305	// regardless of target's state; target is checked only afterwards. Failures
306	// return an empty string and never partial content.
307	func TestExportSourceTargetLineageValidationOrder(t *testing.T) {
308		graph := buildRegisteredGraph(t, [][]string{
309			{"source"},
310			{"report", "source"},
311		})
312		before := snapshotExportGraph(graph)
313	
314		cases := []struct {
315			name    string
316			graph   map[string]*Lineage
317			source  string
318			target  string
319			wantErr string
320		}{
321			{"empty source first", graph, "", "", "dataset name is required"},
322			{"empty source over bad target", graph, "", "ghost", "dataset name is required"},
323			{"missing source first", graph, "ghost", "", "dataset not found: ghost"},
324			{"missing source over missing target", graph, "ghost", "phantom", "dataset not found: ghost"},
325			{"source valid then empty target", graph, "source", "", "dataset name is required"},
326			{"source valid then missing target", graph, "source", "ghost", "dataset not found: ghost"},
327			{"empty graph source", map[string]*Lineage{}, "source", "report", "dataset not found: source"},
328			{"nil graph source", nil, "source", "report", "dataset not found: source"},
329		}
330		for _, tc := range cases {
331			t.Run(tc.name, func(t *testing.T) {
332				out, err := ExportSourceTargetLineage(tc.graph, tc.source, tc.target)
333				if err == nil {
334					t.Fatalf("(%q, %q) succeeded with %q, want error %q",
335						tc.source, tc.target, out, tc.wantErr)
336				}
337				if err.Error() != tc.wantErr {
338					t.Errorf("error = %q, want %q", err, tc.wantErr)
339				}
340				if out != "" {
341					t.Errorf("failed export returned partial content %q, want empty string", out)
342				}
343			})
344		}
345		assertGraphUnchanged(t, before, graph)
346	}
347	
348	// An invalid UTF-8 name on a selected route fails the whole scoped export
349	// under the full export's encoding rule, naming the offending bytes and
350	// returning no document.
351	func TestExportSourceTargetLineageRejectsInvalidUTF8OnRoute(t *testing.T) {
352		graph := buildRegisteredGraph(t, [][]string{
353			{"source"},
354			{"bad\xffmid", "source"},
355			{"report", "bad\xffmid"},
356		})
357		before := snapshotExportGraph(graph)
358	
359		out, err := ExportSourceTargetLineage(graph, "source", "report")
360		if err == nil {
361			t.Fatalf("scoped export with invalid intermediate node succeeded with %q", out)
362		}
363		if out != "" {
364			t.Errorf("failed export returned partial content %q", out)
365		}
366		if !strings.Contains(err.Error(), `"bad\xffmid"`) {
367			t.Errorf("error %q must quote the original bytes", err)
368		}
369		assertGraphUnchanged(t, before, graph)
370	}
371	
372	// The endpoints are selected too: an invalid source or target name fails even
373	// though there is nothing else on the route.
374	func TestExportSourceTargetLineageRejectsInvalidUTF8Endpoints(t *testing.T) {
375		badSource := "src\xff"
376		graph := buildRegisteredGraph(t, [][]string{
377			{badSource},
378			{"report", badSource},
379		})
380		if out, err := ExportSourceTargetLineage(graph, badSource, "report"); err == nil {
381			t.Fatalf("invalid source exported %q", out)
382		} else if !strings.Contains(err.Error(), `"src\xff"`) {
383			t.Errorf("error %q must name the invalid source bytes", err)
384		}
385	
386		badTarget := "rep\xff"
387		graph2 := buildRegisteredGraph(t, [][]string{
388			{"source"},
389			{badTarget, "source"},
390		})
391		if out, err := ExportSourceTargetLineage(graph2, "source", badTarget); err == nil {
392			t.Fatalf("invalid target exported %q", out)
393		} else if !strings.Contains(err.Error(), `"rep\xff"`) {
394			t.Errorf("error %q must name the invalid target bytes", err)
395		}
396	
397		// Source and target identical: that node is selected (the single-node
398		// document), so its invalid name still fails the export.
399		if out, err := ExportSourceTargetLineage(graph2, badTarget, badTarget); err == nil {
400			t.Fatalf("same-name invalid endpoint exported %q", out)
401		} else if !strings.Contains(err.Error(), `"rep\xff"`) {
402			t.Errorf("error %q must name the invalid endpoint bytes", err)
403		}
404	}
405	
406	// Invalid names anywhere outside the selected routes — source's ancestor,
407	// target's independent upstream, a dead-end source downstream, target's
408	// downstream, a standalone dataset — do not block the scoped export.
409	func TestExportSourceTargetLineageIgnoresInvalidNamesOutsideRoutes(t *testing.T) {
410		graph := buildRegisteredGraph(t, [][]string{
411			{"pre\xff"},
412			{"source", "pre\xff"},
413			{"extra\xfe"},
414			{"a", "source", "extra\xfe"},
415			{"b", "source"},
416			{"mid", "b"},
417			{"sidetrack\xfd", "source"},
418			{"lone\xfc"},
419			{"report", "source", "a", "mid", "lone\xfc"},
420			{"view\xfb", "report"},
421			{"isolated\xfa"},
422		})
423	
424		out := mustExportScoped(t, graph, "source", "report")
425		doc := parseExport(t, out)
426		if !reflect.DeepEqual(doc.Nodes, scopedWantNodes) {
427			t.Errorf("nodes = %v, want %v", doc.Nodes, scopedWantNodes)
428		}
429		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, scopedWantEdges) {
430			t.Errorf("edges = %v, want %v", got, scopedWantEdges)
431		}
432	
433		// The same graph's full upstream export of report must still fail on
434		// report's invalid independent upstream, proving the scoped export judges
435		// only its own selected set.
436		if full, err := ExportUpstreamLineage(graph, "report"); err == nil {
437			t.Errorf("full export unexpectedly succeeded with %q, want an encoding error", full)
438		}
439	}
440	
441	// When several selected names are invalid, the string-smallest one is
442	// reported identically under reversed registration and upstream-list orders.
443	func TestExportSourceTargetLineageFirstInvalidNameOrderIndependent(t *testing.T) {
444		fe := "x\xfe"
445		ff := "x\xff"
446		first := buildRegisteredGraph(t, [][]string{
447			{"source"},
448			{fe, "source"},
449			{ff, "source"},
450			{"report", fe, ff},
451		})
452		second := buildRegisteredGraph(t, [][]string{
453			{"source"},
454			{ff, "source"},
455			{fe, "source"},
456			{"report", ff, fe},
457		})
458	
459		_, err1 := ExportSourceTargetLineage(first, "source", "report")
460		_, err2 := ExportSourceTargetLineage(second, "source", "report")
461		if err1 == nil || err2 == nil {
462			t.Fatalf("exports with invalid route nodes must fail, got %v and %v", err1, err2)
463		}
464		if err1.Error() != err2.Error() {
465			t.Errorf("error depends on registration/list order:\nfirst:  %q\nsecond: %q", err1, err2)
466		}
467		if !strings.Contains(err1.Error(), `"x\xfe"`) {
468			t.Errorf("error %q must report the string-smallest invalid name x\\xfe", err1)
469		}
470	}
471	
472	// Missing-name and not-found checks keep priority over encoding validation,
473	// even while the graph holds invalid names.
474	func TestExportSourceTargetLineageErrorPrecedence(t *testing.T) {
475		graph := buildRegisteredGraph(t, [][]string{
476			{"bad\xff"},
477			{"good", "bad\xff"},
478		})
479		for _, tc := range []struct {
480			source  string
481			target  string
482			wantErr string
483		}{
484			{"", "good", "dataset name is required"},
485			{"ghost", "good", "dataset not found: ghost"},
486			{"bad\xff", "", "dataset name is required"},
487			{"bad\xff", "ghost", "dataset not found: ghost"},
488		} {
489			out, err := ExportSourceTargetLineage(graph, tc.source, tc.target)
490			if err == nil {
491				t.Fatalf("(%q, %q) succeeded with %q", tc.source, tc.target, out)
492			}
493			if err.Error() != tc.wantErr {
494				t.Errorf("(%q, %q): error = %q, want %q", tc.source, tc.target, err, tc.wantErr)
495			}
496			if out != "" {
497				t.Errorf("failure returned partial content %q", out)
498			}
499		}
500	}
501	
502	// Success and failure alike leave nodes, both edge directions and list order
503	// untouched.
504	func TestExportSourceTargetLineageReadOnly(t *testing.T) {
505		graph := scopedFixture(t)
506		before := snapshotExportGraph(graph)
507	
508		mustExportScoped(t, graph, "source", "report")
509		mustExportScoped(t, graph, "source", "source")
510		mustExportScoped(t, graph, "source", "sidetrack") // empty result
511		if _, err := ExportSourceTargetLineage(graph, "ghost", "report"); err == nil {
512			t.Fatal("expected a not-found error for the source")
513		}
514		if _, err := ExportSourceTargetLineage(graph, "source", "ghost"); err == nil {
515			t.Fatal("expected a not-found error for the target")
516		}
517		assertGraphUnchanged(t, before, graph)
518	}
519	
520	// A valid unusual name on the selected routes round-trips exactly.
521	func TestExportSourceTargetLineageRoundTripsUnusualValidNames(t *testing.T) {
522		emoji := "source 🚀"
523		quote := `report "x"`
524		graph := buildRegisteredGraph(t, [][]string{
525			{emoji},
526			{"mid", emoji},
527			{quote, "mid"},
528		})
529	
530		doc := parseExport(t, mustExportScoped(t, graph, emoji, quote))
531		wantNodes := []string{emoji, "mid", quote}
532		sort.Strings(wantNodes) // the export's own ordering rule
533		if !reflect.DeepEqual(doc.Nodes, wantNodes) {
534			t.Errorf("nodes = %q, want %q", doc.Nodes, wantNodes)
535		}
536		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, [][2]string{
537			{"mid", quote},
538			{emoji, "mid"},
539		}) {
540			t.Errorf("edges = %q", got)
541		}
542	}
